import { createWaveGeometry } from './waveGeometry'

// Two flowing sheets share one mesh and shader. Their shallow, opposing arcs
// frame the writing instead of cutting diagonally through the entire hero.
const vertexSource = `#version 300 es
precision highp float;
in vec3 a_position;
in vec2 a_uv;
uniform float u_time;
uniform vec2 u_size;
uniform vec3 u_rotation;
uniform vec2 u_position;
uniform float u_phase;
uniform float u_scale;
out vec2 v_uv;

vec2 gradient(vec2 p) {
  float angle = fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453) * 6.2831853;
  return vec2(cos(angle), sin(angle));
}
// Simplex lattice, following Stefan Gustavson's Simplex Noise Demystified.
float noise(vec2 p) {
  vec2 cell = floor(p + (p.x + p.y) * 0.366025404);
  vec2 a = p - cell + (cell.x + cell.y) * 0.211324865;
  vec2 corner = a.x > a.y ? vec2(1, 0) : vec2(0, 1);
  vec2 b = a - corner + 0.211324865;
  vec2 c = a - 0.57735027;
  vec3 falloff = max(0.5 - vec3(dot(a,a), dot(b,b), dot(c,c)), 0.0);
  return dot(falloff * falloff * falloff, vec3(dot(a,gradient(cell)), dot(b,gradient(cell+corner)), dot(c,gradient(cell+1.0)))) * 32.99;
}
vec3 rotateAround(vec3 p, vec3 axis, float angle) {
  axis = normalize(axis);
  return p * cos(angle) + cross(axis, p) * sin(angle) + axis * dot(axis, p) * (1.0 - cos(angle));
}
void main() {
  v_uv = a_uv;
  float phase = u_time * 0.00012 + u_phase;
  float along = a_position.x / 400.0;
  vec3 p = vec3(
    along * u_size.x * 1.55,
    a_position.z / 200.0 * u_size.y * 0.72,
    a_position.y * 7.0
  );
  p = rotateAround(p, vec3(1,0,0), 0.35 + sin(along * 4.2 + phase * 0.6) * 0.6);
  p.y += sin(along * 5.0 + phase) * u_size.y * 0.16;
  p.z += noise(vec2(along * 3.0 + phase * 0.3, a_uv.x * 2.0)) * 45.0;
  p *= u_scale;
  p = rotateAround(p, vec3(0,0,1), u_rotation.z);
  p = rotateAround(p, vec3(0,1,0), u_rotation.y);
  p = rotateAround(p, vec3(1,0,0), u_rotation.x);
  p.xy += u_position * u_size;
  // A shallow orthographic perspective keeps the folds readable at every size.
  p.x -= p.z * 0.02;
  gl_Position = vec4(p.xy / (u_size * 0.5), -p.z / 10000.0, 1.0);
}`

const fragmentSource = `#version 300 es
precision highp float;
in vec2 v_uv;
uniform vec3 u_primary;
uniform vec3 u_light;
uniform vec3 u_accent;
uniform vec3 u_depth;
uniform float u_sheen;
uniform float u_tint;
uniform vec2 u_size;
out vec4 outColor;
float grain(vec2 p) { return fract(sin(dot(p,vec2(12.9898,78.233))) * 43758.5453); }
void main() {
  // The two sides of the fold share the homepage's ink, mist and warm highlight.
  vec3 light = mix(u_primary, u_light, 0.9);
  vec3 depth = mix(u_primary, u_depth, 0.65);
  vec3 color = mix(light,depth,smoothstep(0.06,0.48,v_uv.x));
  color = mix(color,u_accent,smoothstep(0.48,0.85,v_uv.x));
  color = mix(color,light,smoothstep(0.84,1.0,v_uv.x));
  color = mix(color, mix(u_light,u_accent,0.58), u_tint);
  color = mix(color,vec3(1.0),(0.12 + smoothstep(0.25,0.96,v_uv.y) * 0.25) * u_sheen);
  float slope = clamp(0.5 + dFdy(v_uv.y) * u_size.y * 0.99,0.0,1.0);
  float glow = smoothstep(0.0,0.834,pow(slope,0.806));
  float fibers = sin(v_uv.x * 3400.0 + sin(v_uv.y * 19.0) * 2.0) * 0.5 + 0.5;
  float fineFibers = grain(vec2(floor(v_uv.x * 2200.0),floor(v_uv.y * 16.0)));
  color += (1.0 - glow) * 0.25 * u_sheen;
  color += (fibers * 0.025 + fineFibers * 0.028) * glow * u_sheen;
  color += (grain(gl_FragCoord.xy) - 0.5) * 0.012;
  outColor = vec4(clamp(color,0.0,1.0),1.0);
}`

export interface WaveRenderer {
  draw: (time: number) => void
  resize: () => void
  updateColors: () => void
  dispose: () => void
}

export function createWaveRenderer(canvas: HTMLCanvasElement): WaveRenderer | null {
  const gl = canvas.getContext('webgl2', {
    alpha: true,
    antialias: true,
    powerPreference: 'low-power',
  })
  if (!gl) return null
  const shaders: WebGLShader[] = []
  const buffers: WebGLBuffer[] = []
  const program = gl.createProgram()
  const vao = gl.createVertexArray()
  const dispose = () => {
    buffers.forEach((buffer) => gl.deleteBuffer(buffer))
    shaders.forEach((shader) => gl.deleteShader(shader))
    gl.deleteVertexArray(vao)
    gl.deleteProgram(program)
  }
  if (!program || !vao) {
    dispose()
    return null
  }
  for (const [type, source] of [
    [gl.VERTEX_SHADER, vertexSource],
    [gl.FRAGMENT_SHADER, fragmentSource],
  ] as const) {
    const shader = gl.createShader(type)
    if (!shader) {
      dispose()
      return null
    }
    shaders.push(shader)
    gl.shaderSource(shader, source)
    gl.compileShader(shader)
    if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
      dispose()
      return null
    }
    gl.attachShader(program, shader)
  }
  gl.linkProgram(program)
  if (!gl.getProgramParameter(program, gl.LINK_STATUS)) {
    dispose()
    return null
  }
  gl.useProgram(program)
  gl.bindVertexArray(vao)
  const geometry = createWaveGeometry()
  const vertices = gl.createBuffer()
  const indices = gl.createBuffer()
  if (!vertices || !indices) {
    if (vertices) gl.deleteBuffer(vertices)
    if (indices) gl.deleteBuffer(indices)
    dispose()
    return null
  }
  buffers.push(vertices, indices)
  gl.bindBuffer(gl.ARRAY_BUFFER, vertices)
  gl.bufferData(gl.ARRAY_BUFFER, geometry.vertices, gl.STATIC_DRAW)
  gl.bindBuffer(gl.ELEMENT_ARRAY_BUFFER, indices)
  gl.bufferData(gl.ELEMENT_ARRAY_BUFFER, geometry.indices, gl.STATIC_DRAW)
  const position = gl.getAttribLocation(program, 'a_position')
  const uv = gl.getAttribLocation(program, 'a_uv')
  gl.enableVertexAttribArray(position)
  gl.vertexAttribPointer(position, 3, gl.FLOAT, false, 20, 0)
  gl.enableVertexAttribArray(uv)
  gl.vertexAttribPointer(uv, 2, gl.FLOAT, false, 20, 12)
  const uniforms = Object.fromEntries(
    [
      'u_time',
      'u_size',
      'u_primary',
      'u_light',
      'u_accent',
      'u_depth',
      'u_sheen',
      'u_rotation',
      'u_position',
      'u_phase',
      'u_scale',
      'u_tint',
    ].map((key) => [key, gl.getUniformLocation(program, key)]),
  )
  const updateColors = () => {
    const styles = getComputedStyle(canvas)
    for (const [uniform, token] of [
      ['u_primary', '--mf-wave-primary'],
      ['u_light', '--mf-wave-light'],
      ['u_accent', '--mf-wave-accent'],
      ['u_depth', '--mf-wave-depth'],
    ]) {
      const hex = styles.getPropertyValue(token).trim().replace('#', '')
      const rgb = [0, 2, 4].map((offset) => parseInt(hex.slice(offset, offset + 2), 16) / 255)
      gl.uniform3f(uniforms[uniform], rgb[0], rgb[1], rgb[2])
    }
    // Dark material needs a softer specular response, not a white-lit surface
    // hidden behind low opacity. A value of 1 preserves the light appearance.
    const sheen = Number.parseFloat(styles.getPropertyValue('--mf-wave-sheen'))
    gl.uniform1f(uniforms.u_sheen, Number.isFinite(sheen) ? Math.min(1, Math.max(0, sheen)) : 1)
  }
  updateColors()
  gl.enable(gl.DEPTH_TEST)
  gl.clearColor(0, 0, 0, 0)
  const resize = () => {
    const width = Math.max(1, canvas.clientWidth)
    const height = Math.max(1, canvas.clientHeight)
    // Bound fill cost as well as resolution on very wide displays.
    const dpr = Math.min(window.devicePixelRatio || 1, 1.5, Math.sqrt(2400000 / (width * height)))
    canvas.width = Math.max(1, Math.round(width * dpr))
    canvas.height = Math.max(1, Math.round(height * dpr))
    gl.viewport(0, 0, canvas.width, canvas.height)
    gl.uniform2f(uniforms.u_size, width, height)
  }
  resize()
  return {
    resize,
    updateColors,
    draw(time) {
      gl.uniform1f(uniforms.u_time, time)
      gl.clear(gl.COLOR_BUFFER_BIT | gl.DEPTH_BUFFER_BIT)
      // The farther sheet drifts along the upper edge, with a softer material.
      gl.uniform1f(uniforms.u_phase, 2.7)
      gl.uniform1f(uniforms.u_scale, 0.92)
      gl.uniform1f(uniforms.u_tint, 0.48)
      gl.uniform3f(uniforms.u_rotation, -0.35, 0.12, -0.28)
      gl.uniform2f(uniforms.u_position, -0.04, 0.34)
      gl.drawElements(gl.TRIANGLES, geometry.indices.length, gl.UNSIGNED_SHORT, 0)
      // Independent depth gives the closer fold a clean silhouette at crossings.
      gl.clear(gl.DEPTH_BUFFER_BIT)
      gl.uniform1f(uniforms.u_phase, 0.4)
      gl.uniform1f(uniforms.u_scale, 1.08)
      gl.uniform1f(uniforms.u_tint, 0.08)
      gl.uniform3f(uniforms.u_rotation, 0.18, -0.08, 0.24)
      gl.uniform2f(uniforms.u_position, 0.06, -0.38)
      gl.drawElements(gl.TRIANGLES, geometry.indices.length, gl.UNSIGNED_SHORT, 0)
    },
    dispose,
  }
}
